    }
    return jwt.encode(payload, PRIVATE_KEY, algorithm=ALGORITHM, headers={"kid": "local"})


def create_refresh_token(sub: str, jti: str) -> str:
    """Create a refresh token with RS256 signing."""
    payload = {
        "iss": "localhost",
        "exp": datetime.utcnow() + timedelta(days=REFRESH_TOKEN_EXPIRE_DAYS),
        "iat": datetime.utcnow(),
        "jti": jti,
        "sub": sub,
    }
    return jwt.encode(payload, PRIVATE_KEY, algorithm=ALGORITHM, headers={"kid": "local"})


def decode_token(token: str) -> dict:
    """Decode a JWT token using the public key."""
    try:
        return jwt.decode(token, PUBLIC_KEY, algorithms=[ALGORITHM], options={"verify_exp": False})
    except exceptions.PyJWTError:
        raise HTTPException(status_code=401, detail="Invalid token")


def verify_password(plain_password: str, hashed_password: str) -> bool:
