#!/usr/bin/env python3
import json
import sys
import os
import subprocess
import requests
from datetime import datetime, timedelta
from pyjwt import jwt, exceptions
from pyjwt.algorithms import RSAAlgorithm

# Load RSA keys
with open("/app/keys/public.pem", "r") as f:
    PUBLIC_KEY = f.read()

with open("/app/keys/private.pem", "r") as f:
    PRIVATE_KEY = f.read()


def load_tokens():
    """Load tokens from /app/tokens.json"""
    if os.path.exists("/app/tokens.json"):
        with open("/app/tokens.json", "r") as f:
            return json.load(f)
    return None


def save_tokens(tokens):
    """Save tokens to /app/tokens.json"""
    with open("/app/tokens.json", "w") as f:
        json.dump(tokens, f, indent=2)


def acquire():
    """Login and acquire tokens"""
    # Make POST request to /auth/login with username and password
    resp = requests.post(
        "http://127.0.0.1:8000/auth/login",
        json={"username": "admin", "password": "password123"},
        headers={"Content-Type": "application/json"}
    )
    resp.raise_for_status()
    data = resp.json()
    tokens = {
        "access_token": data["access_token"],
        "refresh_token": data["refresh_token"],
        "jti": data["access_token"].split(".")[0] if data["access_token"] else None
    }
    save_tokens(tokens)
    print("Tokens acquired and saved to /app/tokens.json")


def validate(token_type, jti):
    """Validate a token"""
    tokens = load_tokens()
    if not tokens or jti not in tokens:
        print(f"Token {jti} not found in tokens.json")
        return

    token = tokens[jti].get(token_type)
    if not token:
        print(f"Token {jti} does not have a {token_type} type")
        return

    try:
        payload = jwt.decode(token, PUBLIC_KEY, algorithms=["RS256"], options={"verify_exp": True})
        print(f"Token {jti} is valid")
    except exceptions.PyJWTError as e:
        print(f"Token {jti} is invalid: {e}")


def revoke(jti):
    """Revoke a token"""
    tokens = load_tokens()
    if not tokens or jti not in tokens:
        print(f"Token {jti} not found in tokens.json")
        return

    # Remove the token from tokens
    del tokens[jti]
    save_tokens(tokens)
    print(f"Token {jti} revoked and removed from tokens.json")


def retry():
    """Retry acquiring tokens if expired"""
    tokens = load_tokens()
    if not tokens:
        print("No tokens found, acquiring new ones...")
        acquire()
        return

    # Check if tokens are expired
    now = datetime.now()
    for jti in list(tokens.keys()):
        token_type = tokens[jti].get("type")
        if token_type == "access":
            try:
                payload = jwt.decode(tokens[jti]["token"], PUBLIC_KEY, algorithms=["RS256"], options={"verify_exp": True})
                if now > datetime.utcfromtimestamp(payload["exp"]):
                    print(f"Access token {jti} is expired, retrying...")
                    acquire()
                    break
            except exceptions.PyJWTError:
                print(f"Access token {jti} is expired, retrying...")
                acquire()
                break


def main():
    if len(sys.argv) < 2:
        print("Usage: python3 cli.py <command> [args...]")
        print("Commands: acquire, validate, revoke, retry")
        sys.exit(1)

    command = sys.argv[1]

    if command == "acquire":
        acquire()
    elif command == "validate":
        if len(sys.argv) < 3:
            print("Usage: python3 cli.py validate <jti>")
            sys.exit(1)
        validate("access", sys.argv[2])
    elif command == "revoke":
        if len(sys.argv) < 3:
            print("Usage: python3 cli.py revoke <jti>")
            sys.exit(1)
        revoke(sys.argv[2])
    elif command == "retry":
        retry()
    else:
        print(f"Unknown command: {command}")
        sys.exit(1)


if __name__ == "__main__":
    main()
