    username = payload.get("sub")

    if not username:
        logger.warning("No username found in refresh token")
        raise HTTPException(status_code=401, detail="Invalid token")

    # Generate new access token
    import secrets
    new_jti = secrets.token_hex(16)
    new_access_token = create_access_token(sub=username, jti=new_jti)

    # Store new access token in Redis
    redis_client.setex(f"token:{new_jti}", ACCESS_TOKEN_EXPIRE_MINUTES * 60, json.dumps({"type": "access", "token": new_access_token}))

    logger.info(f"User {username} refreshed token successfully")

    return {"access_token": new_access_token}


@app.post("/auth/revoke")
def revoke_token(jti: str = Header(...)) -> dict:
    """Revoke a token by adding it to the blacklist."""
    logger.info(f"Revoking token with JTI: {jti}")

    # Add to blacklist with TTL matching the token's expiration
    try:
        payload = decode_token(jti)
        exp = payload.get("exp")
        if exp:
            ttl = (datetime.utcfromtimestamp(exp) - datetime.utcnow()).total_seconds()
            if ttl <= 0:
                ttl = 0
            redis_client.setex(f"blacklist:{jti}", int(ttl), "revoked")
        else:
            redis_client.setex(f"blacklist:{jti}", 3600, "revoked")  # Default TTL
    except Exception as e:
        logger.warning(f"Error revoking token {jti}: {e}")
        redis_client.setex(f"blacklist:{jti}", 3600, "revoked")

    logger.info(f"Token {jti} revoked successfully")

    return {"status": "revoked"}


@app.post("/auth/validate")
def validate_token_endpoint(request: Request, token: str = Header(...)) -> dict:
    """Validate a token - checks blacklist and expiration."""
    logger.info(f"Validating token: {token[:50]}...")

    if not validate_token(token):
        logger.warning("Token validation failed")
        raise HTTPException(status_code=401, detail="Invalid or expired token")

    logger.info("Token validated successfully")

    return {"valid": True}


